mapper.select:
select
    r.id, r.target_type, r.target_id, r.reporter_id, r.reason_type, r.content,
    r.status, r.handle_by, r.handle_time, r.handle_remark, r.create_time,
    u.nick_name as reporter_nick_name,
    case r.target_type
        when '1' then (select o.title from apply_order o where o.id = r.target_id)
        when '2' then (select v.reason from apply_vote v where v.id = r.target_id)
        when '3' then (select c.content from apply_comment c where c.id = r.target_id)
    end as target_summary
from apply_report r
left join app_user u on u.id = r.reporter_id and u.del_flag = '0'
where r.del_flag = '0'

    and r.id = #{bo.id}


    and r.status = #{bo.status}


    and r.target_type = #{bo.targetType}


    and r.reporter_id = #{bo.userId}


    and r.create_time >= #{bo.beginTime}


    and r.create_time <= #{bo.endTime}

order by r.status asc, r.create_time desc
